/* @lc app=leetcode id=3149 lang=kotlin */ class Solution { fun f(mask: Int, last: Int, nums: IntArray, memo: HashMap<Int, Int>): Int = if (mask == (1 shl nums.size) - 1) Math.abs(last - nums[0]) else memo.getOrPut(mask * 16 + last) { nums.indices.filter { mask shr it and 1 == 0 }.minOf { Math.abs(last - nums[it]) + f(mask or (1 shl it), it, nums, memo) } } fun findPermutation(nums: IntArray): IntArray = HashMap<Int, Int>().let { memo -> generateSequence(1 to 0) { (mask, last) -> if (mask == (1 shl nums.size) - 1) null else nums.indices.filter { mask shr it and 1 == 0 }.first { Math.abs(last - nums[it]) + f(mask or (1 shl it), it, nums, memo) == f(mask, last, nums, memo) }.let { nx -> (mask or (1 shl nx)) to nx } }.map { it.second }.toList().toIntArray() } }